mapper.update:
UPDATE t_oa_police_report
SET deleted_flag = #{deletedFlag}
WHERE report_id = #{reportId}

mapper.select:
SELECT *
FROM t_oa_police_report
WHERE report_number = #{reportNumber}
AND deleted_flag = #{deletedFlag}

    AND report_id != #{excludeReportId}

SELECT report_id, report_number, report_type, CASE report_type WHEN 1 THEN '刑事案件' WHEN 2 THEN '交通事故' WHEN 3 THEN '治安案件' WHEN 4 THEN '火灾事故' WHEN 5 THEN '医疗急救' WHEN 6 THEN '民事纠纷' WHEN 99 THEN '其他' ELSE '未知' END AS report_type_name, report_level, CASE report_level WHEN 1 THEN '紧急' WHEN 2 THEN '高' WHEN 3 THEN '中' WHEN 4 THEN '低' ELSE '未知' END AS report_level_name, reporter_name, reporter_phone, reporter_id_card, report_time, incident_location, description, status, CASE status WHEN 1 THEN '待处理' WHEN 2 THEN '处理中' WHEN 3 THEN '已完成' WHEN 4 THEN '已关闭' ELSE '未知' END AS status_name, handler_id, handler_name, handle_result, handle_time, attachments, remark, create_user_id, create_user_name, create_time, update_time FROM t_oa_police_report
deleted_flag = 0
AND report_number LIKE CONCAT('%', #{queryForm.reportNumber}, '%')
AND report_type = #{queryForm.reportType}
AND report_level = #{queryForm.reportLevel}
AND reporter_name LIKE CONCAT('%', #{queryForm.reporterName}, '%')
AND reporter_phone LIKE CONCAT('%', #{queryForm.reporterPhone}, '%')
AND status = #{queryForm.status}
AND handler_name LIKE CONCAT('%', #{queryForm.handlerName}, '%')
AND incident_location LIKE CONCAT('%', #{queryForm.incidentLocation}, '%')
AND report_time >= #{queryForm.reportTimeStart}
AND report_time <= #{queryForm.reportTimeEnd}
AND create_time >= #{queryForm.createTimeStart}
AND create_time <= #{queryForm.createTimeEnd}
ORDER BY report_time DESC, create_time DESC

SELECT * FROM t_oa_police_report
WHERE reporter_phone = #{reporterPhone}
AND deleted_flag = #{deletedFlag}
ORDER BY report_time DESC

SELECT * FROM t_oa_police_report
WHERE handler_id = #{handlerId}
AND deleted_flag = #{deletedFlag}
ORDER BY report_time DESC
